class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Initialize the status of all users as online (True)
        user_status = [True] * numberOfUsers

        # Initialize mentions count for each user
        mentions = [0] * numberOfUsers

        # Sort events by timestamp to process them in chronological order
        # If timestamps are equal, OFFLINE is processed before MESSAGE as per problem statement
        sorted_events = sorted(events, key=lambda x: x[1])

        # Track pending offline events that will take effect at a future timestamp
        # We'll use a simple approach: process OFFLINE and check if it's time to come back online

        # Process each event
        for event in sorted_events:
            event_type = event[0]
            timestamp = int(event[1])
            rest_of_event = event[2]  # Could be "id<number> ...", "ALL", or "HERE"

            if event_type == "OFFLINE":
                # Parse the user id from the string (e.g., "0" -> 0)
                try:
                    user_id = int(rest_of_event)
                except ValueError:
                    continue

                # Mark the user as going offline; they become online again at timestamp + 60
                # We'll store this in a dictionary mapping user_id to their return timestamp
                if user_status[user_id]:
                    # Only set if currently online (as guaranteed by constraints)
                    # We can't immediately mark as offline because we need to handle the 'return' logic later
                    # Instead, we'll just mark them as offline now. But since we're processing in order,
                    # we need to remember when they come back.
                    # Approach: Use a separate list or dict to track offline timers? 
                    # Actually, simpler: just mark as offline now, but when we encounter a MESSAGE event at the same timestamp,
                    # we must first process any OFFLINE events that happen at this timestamp (which makes them offline),
                    # and then process ONLINE events (coming back) that happen at this timestamp.
                    # Since we are iterating in timestamp order, if multiple events have same timestamp, we need to ensure:
                    # 1. All OFFLINE events at this timestamp are processed BEFORE any MESSAGE events at this timestamp.
                    # 2. All ONLINE events (from OFFLINE +60) at this timestamp are processed BEFORE any MESSAGE events at this timestamp.

                    # To handle this cleanly, we can do two passes per timestamp or sort events with secondary key.
                    # Let's change strategy: instead of sorting events only by timestamp, we also sort by type priority:
                    # Priority: OFFLINE < ONLINE < MESSAGE (so that at same timestamp, OFFLINE and ONLINE come before MESSAGE)
                    # But note: an ONLINE event here means "user comes back online" which happens at timestamp_i (the current one)
                    # So we need to precompute the return times for all OFFLINE events and create corresponding ONLINE events.
                    pass

            elif event_type == "MESSAGE":
                # Determine who is mentioned based on the token
                if rest_of_event == "ALL":
                    # Mention all users regardless of status
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif rest_of_event == "HERE":
                    # Mention only online users
                    for i in range(numberOfUsers):
                        if user_status[i]:
                            mentions[i] += 1
                else:
                    # Specific ids separated by space
                    ids_str = rest_of_event.split()
                    for id_str in ids_str:
                        if id_str.startswith("id"):
                            user_id = int(id_str[2:])
                            if user_status[user_id]:
                                mentions[user_id] += 1

            elif event_type == "ONLINE":
                # This would be created from an OFFLINE event at its return time
                user_id = int(rest_of_event)
                user_status[user_id] = True

        # Revised approach: Preprocess OFFLINE events to generate ONLINE events at timestamp + 60
        # Then sort all events (original MESSAGE and generated ONLINE) plus original OFFLINE by timestamp,
        # with secondary sort key: OFFLINE < ONLINE < MESSAGE (so that at same timestamp, OFFLINE and ONLINE come before MESSAGE)

        # Step 1: Create a new events list including generated ONLINE events
        processed_events = []
        for event in events:
            if event[0] == "OFFLINE":
                ts = int(event[1])
                uid = int(event[2])
                # Add an ONLINE event at ts + 60
                processed_events.append(["ONLINE", str(ts + 60), str(uid)])
                # Keep the original OFFLINE event
                processed_events.append(["OFFLINE", str(ts), event[2]])
            elif event[0] == "MESSAGE":
                processed_events.append(event)

        # Now sort processed_events by timestamp, and for same timestamp, sort by type: OFFLINE < ONLINE < MESSAGE
        type_order = {"OFFLINE": 0, "ONLINE": 1, "MESSAGE": 2}
        processed_events.sort(key=lambda x: (int(x[1]), type_order[x[0]]))

        # Reset status and mentions
        user_status = [True] * numberOfUsers
        mentions = [0] * numberOfUsers

        for event in processed_events:
            event_type = event[0]
            timestamp = int(event[1])
            rest_of_event = event[2]

            if event_type == "OFFLINE":
                user_id = int(rest_of_event)
                user_status[user_id] = False
            elif event_type == "ONLINE":
                user_id = int(rest_of_event)
                user_status[user_id] = True
            elif event_type == "MESSAGE":
                if rest_of_event == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif rest_of_event == "HERE":
                    for i in range(numberOfUsers):
                        if user_status[i]:
                            mentions[i] += 1
                else:
                    ids_str = rest_of_event.split()
                    for id_str in ids_str:
                        if id_str.startswith("id"):
                            user_id = int(id_str[2:])
                            if user_status[user_id]:
                                mentions[user_id] += 1

        return mentions

class Solution:
    def maxDifference(self, s: str) -> int:
        # Count frequencies of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Find the maximum odd frequency and minimum even frequency
        max_odd_freq = -1
        min_even_freq = float('inf')

        for count in freq.values():
            if count % 2 == 1:
                # Odd frequency
                if count > max_odd_freq:
                    max_odd_freq = count
            elif count % 2 == 0:
                # Even frequency
                if count < min_even_freq:
                    min_even_freq = count

        # Return the difference as per problem statement
        return max_odd_freq - min_even_freq

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible starting positions of a substring of length k
        for i in range(n - k + 1):
            start_char = s[i]
            # Check if the substring s[i:i+k] consists of only one distinct character
            is_uniform = True
            for j in range(i, i + k):
                if s[j] != start_char:
                    is_uniform = False
                    break

            if not is_uniform:
                continue

            # Check boundary conditions:
            # If there is a character before the substring, it must be different from start_char
            if i > 0 and s[i-1] == start_char:
                continue

            # If there is a character after the substring, it must be different from start_char
            if i + k < n and s[i+k] == start_char:
                continue

            # All conditions satisfied
            return True

        return False

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True

        # Precompute first and last occurrence of each character
        first_occ = {}
        last_occ = {}
        for idx, char in enumerate(s):
            if char not in first_occ:
                first_occ[char] = idx
            last_occ[char] = idx

        # dp[i] = max number of special substrings using prefix s[:i]
        dp = [0] * (n + 1)

        for i in range(n):
            dp[i+1] = dp[i]  # Option: not include s[i] in a new special substring

            # Try to form a special substring ending at i
            # Iterate l from i down to 0
            for l in range(i, -1, -1):
                # Skip if the substring is the entire string
                if l == 0 and i == n - 1:
                    continue

                char = s[l]
                # Check conditions for the character at l
                # If first_occ[char] < l, then there is an occurrence before l, so invalid
                # If last_occ[char] > i, then there is an occurrence after i, so invalid
                if first_occ.get(char, float('inf')) < l or last_occ.get(char, float('-inf')) > i:
                    # This character violates the condition, and any further left extension will also violate
                    break

                # Update dp
                if dp[l] + 1 > dp[i+1]:
                    dp[i+1] = dp[l] + 1

        return dp[n] >= k

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Calculate the total number of cells on the n x n deck
        total_cells = n * n

        # Calculate the maximum number of containers allowed by weight limit
        # This is floor(maxWeight / w)
        weight_limited_count = maxWeight // w

        # The actual number of containers is the minimum of the two limits
        return min(total_cells, weight_limited_count)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Build the graph using an adjacency list
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection_len = len(set_i & set_j)

                if intersection_len >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Initialize visited array and connected components counter
        visited = [False] * n
        components = 0

        # Iterate over all nodes and perform DFS/BFS for each unvisited node
        for i in range(n):
            if not visited[i]:
                components += 1
                stack = [i]
                visited[i] = True

                while stack:
                    curr = stack.pop()
                    for neighbor in adj[curr]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return components

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n = len(s)
        m = len(t)
        max_len = 0

        # Iterate over all substrings of s
        for i in range(n + 1):
            for j in range(i + 1, n + 1):
                sub_s = s[i:j]
                len_s = len(sub_s)

                # Pruning: if even the longest possible from t doesn't exceed max_len, skip
                if len_s + m <= max_len:
                    continue

                # Iterate over all substrings of t
                for k in range(m + 1):
                    for l in range(k + 1, m + 1):
                        sub_t = t[k:l]
                        total_len = len_s + len(sub_t)

                        # Pruning: if total length is not greater than current max_len, skip
                        if total_len <= max_len:
                            continue

                        candidate = sub_s + sub_t
                        if candidate == candidate[::-1]:
                            max_len = total_len

        return max_len

class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0

        # Check all adjacent pairs including the wrap-around pair (last and first)
        for i in range(n):
            # Current element and next element (with circular wrap-around)
            diff = abs(nums[(i + 1) % n] - nums[i])
            max_diff = max(max_diff, diff)

        return max_diff

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count the frequency of each digit in the string
        from collections import Counter

        freq = Counter(s)

        # Iterate through adjacent pairs in the string
        for i in range(len(s) - 1):
            first_digit = int(s[i])
            second_digit = int(s[i+1])

            # Check if the two digits are different
            if first_digit != second_digit:
                # Check if each digit appears exactly as many times as its numeric value
                if freq[first_digit] == first_digit and freq[second_digit] == second_digit:
